package com.yongdrel.email_template_service.function;
import org.springframework.context.annotation.Bean;import org.springframework.stereotype.Component;import java.util.*;import java.util.function.Function;
@Component public class EmailTemplateFunction{
 private static final Map<String,Set<String>> REQUIRED=Map.of("REGISTRATION_WELCOME",Set.of(),"PAYMENT_PROOF_RECEIVED",Set.of("orderId"),"PAYMENT_APPROVED",Set.of("orderId"),"PAYMENT_REJECTED",Set.of("orderId","reason"),"TICKET_CONFIRMATION",Set.of("orderId","eventName"),"LOTTERY_DRAW_ANNOUNCEMENT",Set.of("eventName"),"WINNER_NOTIFICATION",Set.of("eventName","prize"),"ORDER_EXPIRATION",Set.of("orderId"));
 @Bean public Function<EmailRequest,EmailResponse> renderEmailTemplate(){return this::render;}
 EmailResponse render(EmailRequest r){if(r==null||r.templateType()==null||r.recipientName()==null||r.locale()==null||r.locale().isBlank()||!REQUIRED.containsKey(r.templateType()))throw new IllegalArgumentException("Unsupported or incomplete template request");Map<String,String> v=r.variables()==null?Map.of():r.variables();for(String k:v.keySet())if(k.toLowerCase(Locale.ROOT).matches(".*(jwt|token|password|secret|api.?key|authorization).*"))throw new IllegalArgumentException("Sensitive variable is not allowed");for(String k:REQUIRED.get(r.templateType()))if(!v.containsKey(k)||v.get(k)==null||v.get(k).isBlank())throw new IllegalArgumentException("Missing variable: "+k);String name=escape(r.recipientName()),title=title(r.templateType());String text=message(r.templateType(),v);String plain="Kuzuzangpo, "+r.recipientName()+".\n\n"+text+"\n\nYongdrel Gyenshog";String html="<div style=\"font-family:Arial,sans-serif;color:#24324a\"><h2 style=\"color:#176b87\">Yongdrel Gyenshog</h2><p>Kuzuzangpo, "+name+".</p><p>"+escape(text).replace("\n","<br>")+"</p></div>";return new EmailResponse(title,html,plain);}
 private String title(String t){return switch(t){case"REGISTRATION_WELCOME"->"Welcome to Yongdrel Gyenshog";case"PAYMENT_PROOF_RECEIVED"->"Payment proof received";case"PAYMENT_APPROVED"->"Payment approved";case"PAYMENT_REJECTED"->"Payment rejected";case"TICKET_CONFIRMATION"->"Ticket confirmation";case"LOTTERY_DRAW_ANNOUNCEMENT"->"Lottery draw announcement";case"WINNER_NOTIFICATION"->"Congratulations on your win";case"ORDER_EXPIRATION"->"Order expired";default->throw new IllegalArgumentException("Unsupported template");};}
 private String message(String t,Map<String,String>v){return switch(t){case"REGISTRATION_WELCOME"->"Your registration is complete.";case"PAYMENT_PROOF_RECEIVED"->"We received payment proof for order "+v.get("orderId")+".";case"PAYMENT_APPROVED"->"Payment for order "+v.get("orderId")+" was approved.";case"PAYMENT_REJECTED"->"Payment for order "+v.get("orderId")+" was rejected: "+v.get("reason")+".";case"TICKET_CONFIRMATION"->"Your tickets for "+v.get("eventName")+" are confirmed. Order: "+v.get("orderId")+".";case"LOTTERY_DRAW_ANNOUNCEMENT"->"The lottery draw for "+v.get("eventName")+" has been announced.";case"WINNER_NOTIFICATION"->"You won a prize in "+v.get("eventName")+": "+v.get("prize")+".";case"ORDER_EXPIRATION"->"Order "+v.get("orderId")+" expired before payment was confirmed.";default->throw new IllegalArgumentException("Unsupported template");};}
 private String escape(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
 public record EmailRequest(String templateType,String recipientName,String locale,Map<String,String> variables){}
 public record EmailResponse(String subject,String htmlBody,String plainTextBody){}
}
